        if (currentExp >= maxExp)
        {
            LevelUp();
        }
    }

    private void LevelUp()
    {
        level++;
        currentExp -= maxExp;
        maxExp += level + 3;
        damage += 1;
        maxHealth += 5;
        currentHealth = maxHealth;
    }

    private void Awake()
    {
        if (Instance == null)
        {
            Instance = this;
        }
